package engine;
import java.nio.file.*;
import java.util.*;
public final class Progress {
 public static void write(Path root)throws Exception{
  List<Object> index=Json.list(Json.read(root.resolve("catalog/index.json")));Map<String,List<Map<String,Object>>> byId=new LinkedHashMap<>();
  for(Object x:index){Map<String,Object> item=Json.map(x);Path q=root.resolve(item.get("path").toString()),dir=q.resolve("作答");if(!Files.exists(dir))continue;try(var walk=Files.walk(dir)){for(Path f:walk.filter(p->p.getFileName().toString().equals("session.json")).toList()){Map<String,Object>s=Json.map(Json.read(f));Map<String,Object> record=new LinkedHashMap<>(s);record.put("path",root.relativize(f.getParent()).toString());boolean fresh=false;Path report=f.getParent().resolve("测试结果.json"),source=f.getParent().resolve("sql".equals(item.get("kind"))?"answer.sql":"Solution.java"),test=q.resolve("sql".equals(item.get("kind"))?"测试/sql-cases.json":"测试/cases.json");if(Files.exists(report)&&Files.exists(source)){Map<String,Object>r=Json.map(Json.read(report));fresh=Boolean.TRUE.equals(r.get("passed"))&&Runner.hash(source).equals(r.get("sourceHash"))&&Runner.hash(test).equals(r.get("testHash"));}record.put("currentLocalPassed",fresh);byId.computeIfAbsent(item.get("id").toString(),k->new ArrayList<>()).add(record);}}}
  Json.write(root.resolve("progress/学习记录.json"),byId);StringBuilder md=new StringBuilder("# 学习进度\n\n自动统计："+java.time.OffsetDateTime.now()+"。独立通过要求本轮主动结束、选择独立完成、当前代码和用例版本仍与通过记录一致。题单归属分别统计，同题按题号汇总历史。\n\n| 题单 | 题目位置 | 已练题数 | 独立本地通过 |\n|---|---:|---:|---:|\n");
  for(String plan:List.of("top-interview-150","top-100-liked","sql-free-50","sql-premium-50")){int total=0,started=0,passed=0;for(Object x:index){Map<String,Object>i=Json.map(x);if(!plan.equals(i.get("plan")))continue;total++;List<Map<String,Object>>a=byId.get(i.get("id").toString());if(a!=null){started++;if(a.stream().anyMatch(s->"FINISHED".equals(s.get("status"))&&"1".equals(s.get("mode"))&&Boolean.TRUE.equals(s.get("currentLocalPassed"))))passed++;}}md.append("| ").append(plan).append(" | ").append(total).append(" | ").append(started).append(" | ").append(passed).append(" |\n");}
  md.append("\n## 练习记录\n\n| 题号 | 状态 | 有效分钟 | 本轮方式 | 当前本地通过 |\n|---|---|---:|---|---|\n");for(var e:byId.entrySet())for(var s:e.getValue())md.append("| [LC").append(e.getKey()).append("](../").append(s.get("path")).append("/本轮复盘.md) | ").append(s.get("status")).append(" | ").append(String.format(Locale.ROOT,"%.1f",((Number)s.get("activeMillis")).longValue()/60000.0)).append(" | ").append(s.getOrDefault("mode","未结束")).append(" | ").append(s.get("currentLocalPassed")).append(" |\n");Files.writeString(root.resolve("progress/学习进度.md"),md);
 }
 public static void main(String[]a)throws Exception{write(Main.root());System.out.println("已刷新progress/学习进度.md");}
}
